CREATE TABLE worldbooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),world_id uuid NOT NULL,name text NOT NULL,revision integer NOT NULL DEFAULT 1,FOREIGN KEY(owner_id,world_id) REFERENCES worlds(owner_id,id) DEFERRABLE);
ALTER TABLE lore_entries ADD COLUMN book_id uuid REFERENCES worldbooks(id) DEFERRABLE;
CREATE TABLE worldbook_bindings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),book_id uuid NOT NULL REFERENCES worldbooks(id) DEFERRABLE,scope text NOT NULL CHECK(scope IN ('global','actor','room','group_member')),target_id uuid NOT NULL,actor_id uuid,revision integer NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT true,UNIQUE NULLS NOT DISTINCT(book_id,scope,target_id,actor_id));
